// ResourceConfigV030 is a migration wrapper around the otelconf v0.3.0
// config.Resource type that additionally supports the legacy inline
// resource attribute format.
//
// The declarative format uses the embedded config.Resource fields
// (attributes, schema_url, detectors). The legacy inline format is a
// flat map of attribute name to value; those unknown keys are captured
// into LegacyAttributes.
type ResourceConfigV030 struct {
	// Resource holds the declarative resource configuration. Its fields
	// (Attributes, SchemaUrl, Detectors, AttributesList) are promoted via
	// mapstructure squash.
	config.Resource `mapstructure:",squash"`

	// LegacyAttributes captures the legacy inline resource attribute format,
	// where any unknown top-level key is treated as a resource attribute.
	//
	// A nil value indicates that the corresponding default attribute should
	// be removed from the resource. Nil values are NOT stored in this map.
	LegacyAttributes map[string]any `mapstructure:",remain"`
}

// Unmarshal auto-detects the resource configuration format and populates the
// struct. Known config.Resource keys are captured into the embedded struct;
// any other keys are captured into LegacyAttributes. Legacy keys with a nil
// value are not stored.
func (r *ResourceConfigV030) Unmarshal(conf *confmap.Conf) error {
	if err := conf.Unmarshal(r); err != nil {
		return err
	}
	// Do not store nil-valued legacy keys. A nil value indicates that the
	// corresponding default attribute should be removed, which is handled
	// separately; storing it here would cause it to be serialized back.
	for k, v := range r.LegacyAttributes {
		if v == nil {
			delete(r.LegacyAttributes, k)
		}
	}
	if len(r.LegacyAttributes) == 0 {
		r.LegacyAttributes = nil
	}
	return nil
}

// Validate checks that the resource configuration is well-formed.
func (r *ResourceConfigV030) Validate() error {
	if r.AttributesList != nil {
		return errors.New("resource::attributes_list is not currently supported")
	}
	if len(r.Attributes) > 0 && len(r.LegacyAttributes) > 0 {
		return errors.New("resource::attributes cannot be used together with legacy inline resource attributes")
	}
	for k, v := range r.LegacyAttributes {
		if v == nil {
			continue
		}
		if _, ok := v.(string); !ok {
			return fmt.Errorf("resource::%s: legacy inline resource attribute value must be a string, got %T", k, v)
		}
	}
	return nil
}
