package otelconftelemetry // import "go.opentelemetry.io/collector/service/telemetry/otelconftelemetry"

import (
	"context"
	"errors"
	"fmt"

	"github.com/google/uuid"
	config "go.opentelemetry.io/contrib/otelconf/v0.3.0"
	"go.opentelemetry.io/otel/attribute"
	semconv "go.opentelemetry.io/otel/semconv/v1.40.0"

	"go.opentelemetry.io/collector/component"
	"go.opentelemetry.io/collector/pdata/pcommon"
	"go.opentelemetry.io/collector/service/telemetry"
	"go.opentelemetry.io/collector/service/telemetry/otelconftelemetry/internal/migration"
)

// errMissingCollectorResource is returned by the telemetry providers when the
// settings do not carry a collector resource.
var errMissingCollectorResource = errors.New("missing collector resource")

// defaultAttributeValues returns the default resource attribute values for the
// given build info. It is a variable so that it can be replaced in tests.
var defaultAttributeValues = func(buildInfo component.BuildInfo) (map[string]string, error) {
	instanceUUID, err := uuid.NewRandom()
	if err != nil {
		return nil, err
	}
	return map[string]string{
		string(semconv.ServiceNameKey):       buildInfo.Command,
		string(semconv.ServiceVersionKey):    buildInfo.Version,
		string(semconv.ServiceInstanceIDKey): instanceUUID.String(),
	}, nil
}

func createResource(
	ctx context.Context,
	set telemetry.Settings,
	componentConfig component.Config,
) (pcommon.Resource, error) {
	cfg := componentConfig.(*Config)
	resourceConfig, err := createInitialResourceConfig(set.BuildInfo, &cfg.Resource)
	if err != nil {
		return pcommon.Resource{}, err
	}
	return resourceConfigToPcommon(ctx, resourceConfig)
}

// createInitialResourceConfig combines the default attribute values with the
// resource configuration to produce an otelconf *config.Resource.
//
// Default attributes are populated first, excluding any attribute names that
// were set in the legacy inline format (even nil-valued ones, which indicate
// removal). Non-nil legacy attributes and declarative attributes are then
// appended.
func createInitialResourceConfig(buildInfo component.BuildInfo, cfg *migration.ResourceConfigV030) (*config.Resource, error) {
	defaults, err := defaultAttributeValues(buildInfo)
	if err != nil {
		return nil, err
	}

	attrs := make([]config.AttributeNameValue, 0, len(defaults)+len(cfg.LegacyAttributes)+len(cfg.Attributes))
	for name, value := range defaults {
		if _, ok := cfg.LegacyAttributes[name]; ok {
			// Overridden or removed by the legacy inline format.
			continue
		}
		attrs = append(attrs, config.AttributeNameValue{Name: name, Value: value})
	}
	for name, value := range cfg.LegacyAttributes {
		if value == nil {
			// A nil value indicates the default attribute should be removed.
			continue
		}
		attrs = append(attrs, config.AttributeNameValue{Name: name, Value: value})
	}
	attrs = append(attrs, cfg.Attributes...)

	return &config.Resource{
		SchemaUrl:  schemaURL(cfg),
		Attributes: attrs,
	}, nil
}

// createFixedResourceConfig converts an already-resolved pcommon.Resource into
// an otelconf *config.Resource, carrying over the SchemaUrl from cfg.
func createFixedResourceConfig(cfg *migration.ResourceConfigV030, res *pcommon.Resource) (*config.Resource, error) {
	if res == nil {
		return nil, errMissingCollectorResource
	}
	attrs := make([]config.AttributeNameValue, 0, res.Attributes().Len())
	res.Attributes().Range(func(k string, v pcommon.Value) bool {
		attrs = append(attrs, config.AttributeNameValue{Name: k, Value: v.AsString()})
		return true
	})
	return &config.Resource{
		SchemaUrl:  schemaURL(cfg),
		Attributes: attrs,
	}, nil
}

// schemaURL returns the schema URL to use for the resource, preferring the one
// set in the configuration and falling back to the semantic conventions schema.
func schemaURL(cfg *migration.ResourceConfigV030) *string {
	if cfg.SchemaUrl != nil {
		return cfg.SchemaUrl
	}
	return ptr(semconv.SchemaURL)
}

// resourceConfigToPcommon converts an otelconf *config.Resource into a
// pcommon.Resource, applying the otelconf typed-attribute conversion rules.
func resourceConfigToPcommon(ctx context.Context, resourceConfig *config.Resource) (pcommon.Resource, error) {
	sdk, err := config.NewSDK(
		config.WithContext(ctx),
		config.WithOpenTelemetryConfiguration(config.OpenTelemetryConfiguration{Resource: resourceConfig}),
	)
	if err != nil {
		return pcommon.Resource{}, err
	}
	defer func() { _ = sdk.Shutdown(ctx) }()

	res := pcommon.NewResource()
	sdkRes := sdk.Resource()
	if sdkRes != nil {
		for _, kv := range sdkRes.Attributes() {
			putAttributeValue(res.Attributes(), string(kv.Key), kv.Value)
		}
	}
	return res, nil
}

// putAttributeValue stores an OpenTelemetry attribute value into a pcommon.Map,
// preserving its type.
func putAttributeValue(m pcommon.Map, key string, v attribute.Value) {
	switch v.Type() {
	case attribute.BOOL:
		m.PutBool(key, v.AsBool())
	case attribute.INT64:
		m.PutInt(key, v.AsInt64())
	case attribute.FLOAT64:
		m.PutDouble(key, v.AsFloat64())
	case attribute.STRING:
		m.PutStr(key, v.AsString())
	default:
		m.PutStr(key, v.Emit())
	}
}

func attributeValueString(k string, v attribute.Value) (string, error) {
	if v.Type() != attribute.STRING {
		// We only support string-type resource attributes in the configuration.
		return "", fmt.Errorf("attribute %q: expected string, got %s", k, v.Type())
	}
	return v.AsString(), nil
}

// pcommonAttrsToOTelAttrs gets the Resource attributes to OpenTelemetry attribute.KeyValue slice.
func pcommonAttrsToOTelAttrs(resource *pcommon.Resource) []attribute.KeyValue {
	var result []attribute.KeyValue
	if resource != nil {
		attrs := resource.Attributes()
		attrs.Range(func(k string, v pcommon.Value) bool {
			result = append(result, attribute.String(k, v.AsString()))
			return true
		})
	}
	return result
}
